files.content:
*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  block-size: 100%;
}

body {
  display: grid;
  place-items: center;
  margin: 0;
  block-size: 100%;
}

.loader {
  border: 10px solid #feafe8;
  border-radius: 50%;
  border-block-end-color: #fd24af;
  animation-name: loading;
  inline-size: 100px;
  aspect-ratio: 1/1;
  animation-duration: 1.5s;
}

@keyframes loading {
  0% {
    rotate: 0deg;
  }

  100% {
    rotate: 360deg;
  }
}
